      <Accordion>
        <AccordionItem title="Panel A">Content A</AccordionItem>
        <AccordionItem title="Panel B">Content B</AccordionItem>
      </Accordion>

      <div style={{ marginTop: '2rem' }}>
        <Footer>
          <FooterNavGroup title="Resources">
            <FooterLinkList columns={1} links={footerLinks} />
          </FooterNavGroup>
        </Footer>
      </div>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
